class Solution {
    public int scoreOfParentheses(String s){
        int depth=0,score=0;
        for(int i=0;i<s.length();i++){
            if(s.charAt(i)=='(')depth++;
            else{
                depth--;
                if(s.charAt(i-1)=='(')score+=1<<depth;
            }
        }
        return score;
    }
}

code.kotlin:
class Solution {
    fun scoreOfParentheses(s:String):Int{
        var depth=0;
        var score=0;
        for(i in s.indices)if(s[i]=='(')depth++ else{
            depth--;
            if(s[i-1]=='(')score+=1 shl depth
        };
        return score
    }
}

